namespace help.validator.model;



using help.validator;

public class TOCItemExternal : TOCItem {

	public TOCItemExternal(TOCItem parentItem, Path tocFile, string ID, string text, string target,
			string sortPreference, int lineNumber) : base(parentItem, tocFile, ID, text, target, sortPreference, lineNumber)
    {
	}

	/* @Override */
	public bool validate(LinkDatabase linkDatabase) {
		if (getTargetAttribute() == null) {
			return true; // no target path to validate
		}

		string ID = linkDatabase.getIDForLink(getTargetAttribute());
		if (ID != null) {
			return true; // valid help ID found
		}
		return false;
	}

	/* @Override */
	public string generateTOCItemTag(LinkDatabase linkDatabase, bool isInlineTag,
			int indentLevel) {
		return base.generateTOCItemTag(linkDatabase, isInlineTag, indentLevel);
	}

	/* @Override */
	public string toString() {
		//@formatter:off
		return "<tocitem id=\"" + getIDAttribute() + "\"\n\t\t" +
						"sort=\"" + getSortPreference() + "\"\n\t\t" +
			            "text=\"" + getTextAttribute() + "\"\n\t\t" +
			            "target=\"" + getTargetAttribute() + "\"" +
			    "/>\n\t" +
			   "\tTOC file=\"" + getSourceFile() +"\n";
		//@formatter:on
	}
}
